export const SQLITE_SEMA = "CREATE TABLE addresses (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  sandbox_id TEXT,\n  user_id INTEGER,\n  label TEXT,\n  line1 TEXT,\n  city TEXT,\n  country TEXT,\n  postal_code TEXT,\n  is_default INTEGER\n);\nCREATE TABLE brands (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  sandbox_id TEXT,\n  name TEXT\n);\nCREATE TABLE cart_items (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  sandbox_id TEXT,\n  cart_id INTEGER,\n  variant_id INTEGER,\n  qty INTEGER,\n  unit_price_snapshot REAL,\n  added_at TEXT\n);\nCREATE TABLE carts (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  sandbox_id TEXT,\n  user_id INTEGER,\n  guest_token TEXT,\n  status TEXT,\n  coupon_code TEXT,\n  created_at TEXT\n);\nCREATE TABLE categories (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  sandbox_id TEXT,\n  name TEXT,\n  slug TEXT,\n  parent_id INTEGER\n);\nCREATE TABLE coupons (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  sandbox_id TEXT,\n  code TEXT,\n  kind TEXT,\n  value REAL,\n  min_total REAL,\n  valid_from TEXT,\n  valid_to TEXT,\n  max_uses INTEGER,\n  used_count INTEGER\n);\nCREATE TABLE inventory (\n  variant_id INTEGER PRIMARY KEY AUTOINCREMENT,\n  sandbox_id TEXT,\n  stock_qty INTEGER,\n  reserved_qty INTEGER\n);\nCREATE TABLE order_items (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  sandbox_id TEXT,\n  order_id INTEGER,\n  variant_id INTEGER,\n  name_snapshot TEXT,\n  qty INTEGER,\n  unit_price REAL,\n  line_total REAL\n);\nCREATE TABLE orders (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  sandbox_id TEXT,\n  order_no TEXT,\n  user_id INTEGER,\n  status TEXT,\n  subtotal REAL,\n  discount_total REAL,\n  shipping_total REAL,\n  grand_total REAL,\n  coupon_code TEXT,\n  placed_at TEXT\n);\nCREATE TABLE payments (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  sandbox_id TEXT,\n  order_id INTEGER,\n  method TEXT,\n  status TEXT,\n  amount REAL,\n  txn_ref TEXT,\n  created_at TEXT\n);\nCREATE TABLE product_variants (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  sandbox_id TEXT,\n  product_id INTEGER,\n  size TEXT,\n  color TEXT,\n  sku TEXT,\n  price_delta REAL\n);\nCREATE TABLE products (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  sandbox_id TEXT,\n  sku TEXT,\n  name TEXT,\n  description TEXT,\n  category_id INTEGER,\n  brand_id INTEGER,\n  price REAL,\n  currency TEXT,\n  is_active INTEGER,\n  created_at TEXT\n);\nCREATE TABLE reviews (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  sandbox_id TEXT,\n  product_id INTEGER,\n  user_id INTEGER,\n  rating INTEGER,\n  comment TEXT,\n  status TEXT,\n  created_at TEXT\n);\nCREATE TABLE sessions (\n  jti TEXT,\n  sandbox_id TEXT,\n  user_id INTEGER,\n  issued_at TEXT,\n  expires_at TEXT,\n  revoked_at TEXT,\n  PRIMARY KEY (jti)\n);\nCREATE TABLE shipments (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  sandbox_id TEXT,\n  order_id INTEGER,\n  carrier TEXT,\n  tracking_no TEXT,\n  status TEXT,\n  shipped_at TEXT,\n  delivered_at TEXT\n);\nCREATE TABLE users (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  sandbox_id TEXT,\n  email TEXT,\n  password_hash TEXT,\n  name TEXT,\n  is_active INTEGER,\n  created_at TEXT\n);"

